import {FISH,FISHING_POOLS} from './model.js';import {FISHING_SPOTS} from './layout.js';import {remainingFish} from '../state/fishing.js';
const notes={'petal-minnow':'꽃잎처럼 연분홍빛인 작은 물고기','moon-carp':'달빛처럼 노란 동그란 몸','ribbon-mackerel':'푸른 몸에 리본 같은 줄무늬','star-bream':'살구빛 몸에 작은 별 같은 점'};
export function natureEntries(fishing){return Object.entries(FISH).map(([id,f])=>{const total=fishing?.counts?.[id]??0,first=fishing?.firstCatch?.[id],known=total>0;return {id,known,name:known?f.label:'아직 만나지 못했어요',description:known?notes[id]:'그림자 속 친구를 물가에서 만나 봐요',habitat:f.habitat==='pond'?'연못':'바다',total,remaining:remainingFish(fishing,id),meals:fishing?.meals?.[id]??0,firstDate:first?.at?new Date(first.at).toLocaleDateString('ko-KR'):null,firstPlace:first?.spotId?FISHING_SPOTS[first.spotId]?.shortLabel:null,commonPlaces:Object.entries(FISHING_POOLS).filter(([,pool])=>pool.find(([fishId])=>fishId===id)?.[1]===4).map(([key])=>FISHING_SPOTS[key].shortLabel)};});}
export function natureGuideHTML(fishing){const entries=natureEntries(fishing),known=entries.filter(e=>e.known).length;return `<button class="modal-x" data-close aria-label="자연도감 닫기">×</button><h2 id="modal-title">도름이 자연도감</h2><p>물고기 ${known} / ${entries.length} 발견 · 별빛 마을의 상상 속 친구들이에요</p><div class="nature-fish-grid">${entries.map(e=>`<article class="nature-fish ${e.known?'known':'unknown'}"><img src="fishing/guide/${e.id}.webp" alt="${e.known?e.name:'아직 발견하지 못한 물고기 그림자'}"><h3>${e.name}</h3><p>${e.description}</p><p class="nature-place">${e.habitat} · 주로 ${e.commonPlaces.join(' · ')}</p>${e.known?`<dl><div><dt>지금까지 발견</dt><dd>${e.total}마리</dd></div><div><dt>재료가방</dt><dd>${e.remaining}마리</dd></div><div><dt>구워 먹은 수</dt><dd>${e.meals}마리</dd></div></dl><p class="nature-first">${e.firstDate?'처음 만난 날 '+e.firstDate+' · '+e.firstPlace:'이전 기록에서 이어온 친구 · 첫 날짜와 장소는 알 수 없어요'}</p>`:'<p class="nature-first">그림 팻말이 있는 물가를 찾아보세요</p>'}</article>`).join('')}</div><p class="caption">요리해도 지금까지 만난 기록과 첫 발견은 사라지지 않아요. 가방 수량은 요리에 쓴 물고기를 뺀 수예요.</p>`;}
